# ── Shared helpers for the one-file Colab step scripts (bundled by build.py) ──
import base64
import os
import shutil
import subprocess
import sys
import time
import zipfile

BASE = os.environ.get("RADARNET_BASE", "/content")      # override only for local testing
WORK = os.path.join(BASE, "radarnet")
PY = os.path.join(WORK, "python")
RAW = os.path.join(BASE, "raw")
DRIVE_ROOT = os.path.join(BASE, "drive/MyDrive/RADARNET-FX-results")
KAGGLE_URL = os.environ.get("RADARNET_URL",  # override only for local testing
                            "https://www.kaggle.com/api/v1/datasets/download/pinxau1000/radioml2018")
H5_NAME = "GOLD_XYZ_OSC.0001_1024.hdf5"
SPLIT_FILES = ["X_train.npy", "y_train.npy", "X_val.npy", "y_val.npy", "X_test.npy", "y_test.npy"]

LOG = []
OUT = None          # set by each step to Drive/RADARNET-FX-results/<step>


def say(msg=""):
    print(msg, flush=True)
    LOG.append(str(msg))


def banner(n, msg):
    say("")
    say("=" * 70)
    say(f" STEP {n}: {msg}")
    say("=" * 70)


def run(cmd, cwd=PY):
    """Run a command, stream its output, keep it for the log, stop on failure."""
    say(f"$ {cmd}")
    p = subprocess.Popen(cmd, shell=True, cwd=cwd, stdout=subprocess.PIPE,
                         stderr=subprocess.STDOUT, text=True)
    for line in p.stdout:
        line = line.rstrip("\n")
        print(line, flush=True)
        if "\r" not in line:
            LOG.append(line)
    if p.wait() != 0:
        raise SystemExit(f"\n*** Command failed: {cmd}\n*** Copy everything above and send it to Claude.")


def save_log(step):
    os.makedirs(OUT, exist_ok=True)
    with open(os.path.join(OUT, f"{step}_log.txt"), "w") as f:
        f.write("\n".join(LOG) + "\n")


def unpack_and_mount(step):
    """Write the embedded project files and mount Google Drive."""
    global OUT
    banner(1, "unpacking project files")
    for rel, b64 in EMBEDDED_FILES.items():
        path = os.path.join(WORK, rel)
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "wb") as f:
            f.write(base64.b64decode(b64))
        say(f"  wrote {rel}")
    banner(2, "connecting Google Drive (approve the pop-up)")
    from google.colab import drive
    drive.mount(os.path.join(BASE, "drive"))
    OUT = os.path.join(DRIVE_ROOT, step)
    os.makedirs(OUT, exist_ok=True)
    say(f"  results folder: {OUT}")


def get_radioml(n):
    """Download + extract RadioML 2018.01A once per Colab session; returns the .hdf5 path."""
    h5 = os.path.join(RAW, H5_NAME)
    if os.path.exists(h5):
        banner(n, "RadioML 2018.01A already downloaded in this session")
        return h5
    banner(n, "downloading RadioML 2018.01A (~18 GB, usually 5-15 min)")
    free_gb = shutil.disk_usage(BASE).free / 1e9
    say(f"  free disk: {free_gb:.0f} GB")
    if free_gb < 45:
        raise SystemExit("*** Not enough disk space (need ~45 GB). "
                         "Runtime → Disconnect and delete runtime, then try again.")
    os.makedirs(RAW, exist_ok=True)
    zpath = os.path.join(RAW, "archive.zip")
    run(f'curl -L --fail --retry 5 -C - -o "{zpath}" "{KAGGLE_URL}"', cwd=RAW)
    say("  extracting the .hdf5 file (a few minutes) …")
    with zipfile.ZipFile(zpath) as z, z.open(H5_NAME) as src, open(h5, "wb") as dst:
        shutil.copyfileobj(src, dst, length=64 << 20)
    os.remove(zpath)
    say(f"  dataset ready: {os.path.getsize(h5) / 1e9:.1f} GB")
    return h5


def cached(src_dir, cache_dir, files):
    """Copy files from a Drive cache if all are present; True on success."""
    if all(os.path.exists(os.path.join(cache_dir, f)) for f in files):
        shutil.copytree(cache_dir, src_dir, dirs_exist_ok=True)
        return True
    return False


def finish(step, t0, lines):
    save_log(step)
    say("")
    say("#" * 70)
    say(f" ALL DONE in {(time.time() - t0) / 60:.0f} min.")
    for line in lines:
        say(" " + line)
    say("#" * 70)
    save_log(step)


def entry(main, step):
    try:
        main()
    except SystemExit as e:
        print(e)
        try:
            save_log(step)
        except Exception:
            pass


# ── Step 2 (run in Colab with:  %run radarnet_step2.py ) ─────────────────────
# Option A: RF anomaly dataset on RadioML 2018.01A + training + baselines +
# integer (hardware) model, end to end.
#
#   1-2. unpack project files, mount Google Drive
#   3.   download RadioML 2018.01A (skipped if the dataset is cached in Drive)
#   4.   generate the anomaly dataset (7 classes, JSR -10..+20 dB, base SNR >= 0 dB, AGC)
#   5.   train RadarNet-1D on the GPU
#   6.   classical baselines (energy detector, expert features + GBM)
#   7.   integer hardware model: calibrate + evaluate
#   8.   summary table, figures, RTL test vectors
#   9.   save everything to Drive/RADARNET-FX-results/step2

ANOM_FILES = SPLIT_FILES + ["meta_train.npz", "meta_val.npz", "meta_test.npz",
                            "dataset_info.json"]
DATASET_VERSION = 2   # must match anomaly_dataset.DATASET_VERSION


def cache_is_current(cache_dir):
    import json
    info = os.path.join(cache_dir, "dataset_info.json")
    if not os.path.exists(info):
        return False
    with open(info) as f:
        return json.load(f).get("version") == DATASET_VERSION


def main():
    t0 = time.time()
    unpack_and_mount("step2")

    import torch
    if not torch.cuda.is_available() and not os.environ.get("RADARNET_ALLOW_CPU"):
        raise SystemExit(
            "\n*** No GPU in this session. Training needs one.\n"
            "*** Runtime → Change runtime type → choose 'T4 GPU' → Save,\n"
            "*** then upload radarnet_step2.py again and run  %run radarnet_step2.py")
    say(f"  GPU: {torch.cuda.get_device_name(0) if torch.cuda.is_available() else 'none (CPU test mode)'}")

    data_cache = os.path.join(DRIVE_ROOT, "data_anom")
    data_dir = os.path.join(WORK, "data_anom")
    if cache_is_current(data_cache) and cached(data_dir, data_cache, ANOM_FILES):
        banner(3, "anomaly dataset already in Drive — copied it (download skipped)")
    else:
        if os.path.exists(data_cache):
            say("  the anomaly dataset in Drive is from an older version — regenerating it")
            shutil.rmtree(data_cache)
        h5 = get_radioml(3)
        banner(4, "generating the anomaly dataset (~5 min)")
        run(f'python anomaly_dataset.py --hdf5 "{h5}" --out-dir ../data_anom '
            + os.environ.get("RADARNET_DATASET_ARGS", ""))
        say("  saving the dataset to Drive so later runs skip this …")
        shutil.copytree(data_dir, data_cache, dirs_exist_ok=True)

    ck = os.path.join(WORK, "checkpoints_anom")
    banner(5, "training RadarNet-1D (about 20-40 min on a T4 GPU)")
    run("python train_anomaly.py --data-dir ../data_anom --out-dir ../checkpoints_anom "
        + os.environ.get("RADARNET_TRAIN_ARGS", ""))

    banner(6, "classical baselines (about 5-10 min)")
    run("python baselines.py --data-dir ../data_anom --out-dir ../checkpoints_anom")

    banner(7, "integer hardware model: calibrate + evaluate on the test set")
    intq = os.path.join(ck, "radarnet_anom_intq.npz")
    pth = os.path.join(ck, "radarnet_anom_best.pth")
    run(f"python int_quant.py calib --checkpoint {pth} --data-dir ../data_anom --out {intq}")
    run(f"python int_quant.py eval --intq {intq} --checkpoint {pth} "
        f"--data-dir ../data_anom --report-dir {ck}")

    banner(8, "summary table, figures, RTL test vectors")
    run("python anom_report.py --data-dir ../data_anom --ck-dir ../checkpoints_anom")

    banner(9, "saving results to Google Drive")
    shutil.copytree(ck, OUT, dirs_exist_ok=True)
    for f in sorted(os.listdir(ck)):
        say(f"  {OUT}/{f}")
    finish("step2", t0, [
        "Send Claude: the table printed in STEP 8 (or the file summary.md).",
        "Then download the whole folder Drive/RADARNET-FX-results/step2",
        "into RADARNET-FX/checkpoints_anom/ on your laptop."])


entry(main, "step2")
